#version 460
#extension GL_GOOGLE_include_directive : require
#include "pelican_sets.glsl"
#include "pelican_sample_table.glsl"
#include "pelican_resource_ports.glsl"
// AB-1s: the right half reads band 0 of the baked table on the GPU; the
// left half the number the graph hands the pass (value.sample_table through a
// render.buffer). The top band is a fixed reference grey. UX-13a: the two
// buffers are read through the include the pass's ports generate
// (pelican_resource_<port>, at the bindings the engine gives them); before a
// port is there its half reads 0.
layout(set = PELICAN_SET_PASS_INPUT, binding = 0) uniform sampler2D beat_table;

layout(location = 0) in vec2 inTexCoord;
layout(location = 0) out vec4 outColor;

void main() {
#ifdef PELICAN_RESOURCE_PORT_beat_layout
    vec4 l = pelican_resource_beat_layout.values[0];
#else
    vec4 l = vec4(1.0, 1.0, 0.01, 0.0);
#endif
    float band = pelican_sample_table(beat_table, 1u, uint(l.x), uint(l.y), l.z, l.w);
#ifdef PELICAN_RESOURCE_PORT_value_level
    float level = pelican_resource_value_level.values[0];
#else
    float level = 0.0;
#endif
    float shown = inTexCoord.x < 0.5 ? clamp(level * 8.0, 0.0, 1.0) : clamp(band * 6.0, 0.0, 1.0);
    outColor = vec4(vec3(inTexCoord.y < 0.1 ? 0.5 : shown), 1.0);
}
